package com.example.rokidgeminisecretary;
public class ReferenceDraftPolicyTest{static int n;static void ok(boolean b){if(!b)throw new AssertionError(n);n++;}public static void main(String[] a){String old="画像1：",next="画像2：",tail="日程は？\n場所も教えて🙂";ok(ReferenceDraftPolicy.retarget(old+tail,old,next,100).equals(next+tail));ok(ReferenceDraftPolicy.retarget(old+tail,old,old,100).equals(old+tail));ok(ReferenceDraftPolicy.retarget("別の下書き",old,next,100).equals(next));ok(ReferenceDraftPolicy.retarget("",old,next,100).equals(next));ok(ReferenceDraftPolicy.retarget(null,null,next,100).equals(next));ok(ReferenceDraftPolicy.bound(old+tail,old));ok(!ReferenceDraftPolicy.bound("別の下書き",old));ok(!ReferenceDraftPolicy.bound("", ""));String s=ReferenceDraftPolicy.retarget(old+tail,old,next,100);ok(ReferenceDraftPolicy.retarget(s,next,old,100).equals(old+tail));boolean failed=false;try{ReferenceDraftPolicy.retarget(old+tail,old,next,3);}catch(IllegalArgumentException e){failed=true;}ok(failed);System.out.println("PASS "+n+" reference draft recovery checks");}}
